draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30, H/2 + 70);
  ctx.stroke();

  // add arms and hands that move up and down
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 + 70);
  ctx.lineTo(W/2 - 50, H/2 + 70 + 30 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 + 70 + 30 * Math.sin(t), 10, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 30, H/2 + 70);
  ctx.lineTo(W/2 + 50, H/2 + 70 + 30 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 70 + 30 * Math.sin(t), 10, 0, 2*Math.PI);
  ctx.stroke();

  // add a rising line to represent growth and dignity
  ctx.beginPath();
  ctx.moveTo(W/2, H);
  ctx.lineTo(W/2, H - 100 * Math.sin(t + Math.PI/2));
  ctx.stroke();

  ctx.restore();
}
